36: 
37: const router = useRouter()
38: const route = useRoute()
39: const userStore = useUserStore()
40: const agentStore = useAgentStore()
41: 
42: // 状态
43: const loading = ref(true)
44: const error = ref(false)
45: const errorTitle = ref('登录失败')
46: const errorMessage = ref('处理登录请求时发生错误')
47: 
48: // 返回登录页
49: const goToLogin = () => {
50:   router.push('/login')
51: }
52: 
53: // 处理 OIDC 回调 - 从 URL 参数中获取一次性 code
54: const handleCallback = async () => {
55:   try {
56:     const code = route.query.code
57: 
58:     // 检查必要的参数
59:     if (!code || typeof code !== 'string') {
60:       loading.value = false
61:       error.value = true
62:       errorTitle.value = '参数错误'
63:       errorMessage.value = '缺少有效的登录 code，请重新登录'
64:       return
65:     }
66: 
67:     const tokenData = await authApi.exchangeOIDCCode(code)
68: 
69:     await router.replace({ path: route.path, query: {} })
70: 
71:     // 更新用户状态
72:     userStore.token = tokenData.access_token
73:     userStore.userId = tokenData.uid
74:     userStore.username = tokenData.username
75:     userStore.uid = tokenData.uid || ''
76:     userStore.phoneNumber = tokenData.phone_number || ''
77:     userStore.avatar = tokenData.avatar || ''
78:     userStore.userRole = tokenData.role || 'user'
79:     userStore.departmentId = tokenData.department_id || null
