83:     localStorage.setItem('user_token', tokenData.access_token)
84: 
85:     // 显示成功消息
86:     message.success('登录成功')
87: 
88:     // 获取重定向路径并清理 OIDC 相关标记
89:     const redirectPath = sessionStorage.getItem('oidc_redirect') || '/'
90:     sessionStorage.removeItem('oidc_redirect')
91:     clearAutoStartAttempt()
92: 
93:     loading.value = false
94: 
95:     // 延迟跳转，让用户看到成功提示
96:     setTimeout(async () => {
