98:       if (redirectPath === '/') {
99:         try {
100:           await agentStore.initialize()
101:           router.push('/agent')
102:         } catch (err) {
103:           console.error('获取智能体信息失败:', err)
104:           router.push('/agent')
105:         }
106:       } else {
